        "content": "[{\"icon\":\"ShoppingBag\",\"title\":\"Multi-Vendor Architecture\",\"description\":\"Empower hundreds of individual grocery and retail sellers with dedicated vendor portals.\"},{\"icon\":\"Zap\",\"title\":\"Live GPS Order Tracking\",\"description\":\"Socket-driven real-time driver tracking from store pickup to customer doorstep.\"},{\"icon\":\"ShieldCheck\",\"title\":\"Complete Source Code Included\",\"description\":\"Full access to Flutter customer app, driver app, and Laravel admin source code.\"},{\"icon\":\"Layers\",\"title\":\"Multi-Branch & Inventory\",\"description\":\"Manage multiple warehouse locations, zone delivery radiuses, and stock balances.\"}]",
